INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p932266-ias322', 'stk-fares2', 'IAS 322', 'info', '{"desc": "الدكتور خالد المزيني\n\nمقرر الاختبار الثاني ( 25 ) درجة\n- حق الحياة . الصفحات ( 121 – 131 )\n- حق المساواة الصفحات ( 132 – 149 )\n- مقاصد الشريعة ( الضروريات الخمسة ) الحدود و العقوبات ، والشبهات المثارة حولها الصفحات ( 155 –\n174 ) .\n- حق الأسرة . الصفحات 200 – 238\n\nيقولك بالمذاكره النقص ولا الزود", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/material-of-ias-322/114999/11", "user": "fares2", "ts": 1321551493000, "tid": 114999, "pn": 11}}', 1321551493000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p768614-ias322', 'stk-search_engine', 'IAS 322', 'info', '{"desc": "ياخي كرهت الماده مره .\n\nماعمري خبصت في اسلامي وجاني اكتئاب الا من بعد ما اختبرت الفاينل حق الماده هاذي.\n\nانا مني عارف هما بس يبغوا يحطوا اي اختيارات من راسهم ولا ايش؟ الف مليون سؤال حاطيين لي فيه جميع ماذكر والعكس. ياخي في اسئله تكون معقده لمن تحط فيها جميع ماذكر والي عكسه بيعدم ابو الشغله وبتصير اسوأ.\nوللمعلوميه تراني مذاكر ومهتم للماده واحد عنده تحذير ٢ فمايحتاج اقولكم عن الحاله!\n\nلابارك الله في الشيطان بس.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-322/101089/4", "user": "Search_Engine", "ts": 1295634756000, "tid": 101089, "pn": 4}}', 1295634756000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1313175-ias322', 'stk-big_h', 'IAS 322', 'info', '{"desc": "السلام عليكم\n\nانا عند الدكتور الخليفي وشاكك شوية في الماتيريل اللي معطينا هو\nيعني مثلا كاتبلنا حرية الدين من 189 الى 301 , وتعال شوف ما تلاقي حرية دين ومو معقول 100 صفحة تذاكر\n\nالمهم اللي عنده الماتيريل يريت يرفعه لنا , خصوصا حق الاختبار الثاني واخر جزء , ويعطيكم العافية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-322/154710/1", "user": "Big_H", "ts": 1388620630000, "tid": 154710, "pn": 1}}', 1388620630000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1313192-ias322', 'stk-user7706', 'IAS 322', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nإعلان حول منهج الاختبار النهائي\nلمادة الحقوق (داع 322) فصل (131)\n\nالمفردات المطلوبة في الاختبار النهائي ثماني مفردات، وهي وفقا للطبعات: الثانية وما بعدها:\n\nالتكريم الإلهي للإنسان 28 – 42\nحق الحياة 121 – 131\nحق الأسرة 200 – 238\nحق التعليم 239– 243\nحق العمل 244 –258\nحق التملك 259– 268\nحق الحرية 269 – 301\nحق التقاضي 310 – 329\nويلحظ أن المفردات التي أرقامها (2 و3 و4 و5 و7 و8) غير مطلوبة في الاختبار النهائي\n\nمع دعوات أساتذة المادة للجميع بالتوفيق\n\n^ رسالة الدكتور سعيد القحطاني", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias-322/154710/2", "user": "user7706", "ts": 1388623091000, "tid": 154710, "pn": 2}}', 1388623091000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p985127-ias322', 'stk-mr.all', 'IAS 322', 'srcP', '{"html": "بالمرفقات مواعيد الاختبارات والمواضيع المطلوبة<br>بالتوفيق للجميع<br><br>​<span data-fid=\"stk-f985127-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f985127-0": {"name": "داع-322.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/98e7223a3207663805f7f3b1e0a5e892703c280a5b38526653a28b57c605be1f"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ias322/119553/4", "user": "Mr.All", "ts": 1329135325000, "tid": 119553, "pn": 4}}', 1329135325000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
